import assert from 'node:assert/strict';
import {shipping} from './shipping.mjs';
assert.equal(shipping(1000),500);

import {status} from './http.mjs';
const discount = .9;
export const quote = cents => status() === 200 ? cents * discount : 0;

import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {quote} from './domain.mjs';
assert.equal(quote(100),90);
assert.match(readFileSync(new URL('./domain.mjs',import.meta.url),'utf8'),/const discount = \.9/);

import assert from 'node:assert/strict';
import {expedite} from './fee.mjs';
assert.equal(expedite(false), 0);
